function icon(string $name, string $class = ''): string
{
    $inner = ICONS[$name] ?? ICONS['circle-alert'];
    return '<svg class="i ' . $class . '" viewBox="0 0 24 24" aria-hidden="true" focusable="false">' . $inner . '</svg>';
}

function brand_icon(string $name): string
{
    $d = BRAND_ICONS[$name] ?? '';
    return '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="' . $d . '"/></svg>';
}
